CREATE TABLE public.products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id), sku text NOT NULL CHECK(length(btrim(sku)) BETWEEN 1 AND 80), name text NOT NULL CHECK(length(btrim(name)) BETWEEN 1 AND 160), category text NOT NULL DEFAULT '' CHECK(length(category)<=100), description text NOT NULL DEFAULT '' CHECK(length(description)<=5000), unit text NOT NULL DEFAULT 'piece' CHECK(length(btrim(unit)) BETWEEN 1 AND 40), status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived')), created_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,id));
GRANT SELECT,INSERT ON public.products TO authenticated; GRANT UPDATE(sku,name,category,description,unit,status) ON public.products TO authenticated; GRANT ALL ON public.products TO service_role;
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
CREATE POLICY products_read ON public.products FOR SELECT TO authenticated USING(public.is_org_member(organization_id));
CREATE POLICY products_insert ON public.products FOR INSERT TO authenticated WITH CHECK(public.has_org_role(organization_id,ARRAY['owner','admin']) AND created_by=auth.uid());
CREATE POLICY products_update ON public.products FOR UPDATE TO authenticated USING(public.has_org_role(organization_id,ARRAY['owner','admin'])) WITH CHECK(public.has_org_role(organization_id,ARRAY['owner','admin']));
CREATE UNIQUE INDEX products_unique_sku ON public.products(organization_id,lower(btrim(sku)));
CREATE INDEX products_catalogue ON public.products(organization_id,status,category,name,id);
CREATE TABLE public.entity_products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,entity_id uuid NOT NULL,product_id uuid NOT NULL,supplier_sku text NOT NULL DEFAULT '' CHECK(length(supplier_sku)<=80),moq numeric(18,6) NOT NULL DEFAULT 1 CHECK(moq>0 AND moq<1000000000000),capacity text NOT NULL DEFAULT '' CHECK(length(capacity)<=500),packaging text NOT NULL DEFAULT '' CHECK(length(packaging)<=1000),lead_time_days integer CHECK(lead_time_days BETWEEN 0 AND 3650),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,id),UNIQUE(organization_id,entity_id,product_id),FOREIGN KEY(organization_id,entity_id) REFERENCES public.entities(organization_id,id),FOREIGN KEY(organization_id,product_id) REFERENCES public.products(organization_id,id));
GRANT SELECT,INSERT ON public.entity_products TO authenticated; GRANT UPDATE(supplier_sku,moq,capacity,packaging,lead_time_days) ON public.entity_products TO authenticated; GRANT ALL ON public.entity_products TO service_role;
ALTER TABLE public.entity_products ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.can_trade_entity(p_org uuid,p_entity uuid,p_write boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT public.is_org_member(p_org) AND (NOT p_write OR public.has_org_role(p_org,ARRAY['owner','admin'])) AND EXISTS(SELECT 1 FROM public.entities e WHERE e.id=p_entity AND e.organization_id=p_org AND public.can_entity(p_org,e.entity_type_id,'read') AND (NOT p_write OR public.can_entity(p_org,e.entity_type_id,'update'))) $$;
REVOKE ALL ON FUNCTION public.can_trade_entity(uuid,uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.can_trade_entity(uuid,uuid,boolean) TO authenticated;
CREATE POLICY links_read ON public.entity_products FOR SELECT TO authenticated USING(public.can_trade_entity(organization_id,entity_id,false));
CREATE POLICY links_insert ON public.entity_products FOR INSERT TO authenticated WITH CHECK(public.can_trade_entity(organization_id,entity_id,true));
CREATE POLICY links_update ON public.entity_products FOR UPDATE TO authenticated USING(public.can_trade_entity(organization_id,entity_id,true)) WITH CHECK(public.can_trade_entity(organization_id,entity_id,true));
CREATE TABLE public.contacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,entity_id uuid NOT NULL,name text NOT NULL CHECK(length(btrim(name)) BETWEEN 1 AND 160),email text NOT NULL DEFAULT '' CHECK(email='' OR email ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'),phone text NOT NULL DEFAULT '' CHECK(length(phone)<=80),position text NOT NULL DEFAULT '' CHECK(length(position)<=100),notes text NOT NULL DEFAULT '' CHECK(length(notes)<=2000),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(organization_id,entity_id) REFERENCES public.entities(organization_id,id));
GRANT SELECT,INSERT,DELETE ON public.contacts TO authenticated; GRANT UPDATE(name,email,phone,position,notes) ON public.contacts TO authenticated; GRANT ALL ON public.contacts TO service_role;
ALTER TABLE public.contacts ENABLE ROW LEVEL SECURITY;
CREATE POLICY contacts_read ON public.contacts FOR SELECT TO authenticated USING(public.can_trade_entity(organization_id,entity_id,false));
CREATE POLICY contacts_insert ON public.contacts FOR INSERT TO authenticated WITH CHECK(public.can_trade_entity(organization_id,entity_id,true));
CREATE POLICY contacts_update ON public.contacts FOR UPDATE TO authenticated USING(public.can_trade_entity(organization_id,entity_id,true)) WITH CHECK(public.can_trade_entity(organization_id,entity_id,true));
CREATE POLICY contacts_delete ON public.contacts FOR DELETE TO authenticated USING(public.can_trade_entity(organization_id,entity_id,true));
CREATE UNIQUE INDEX contacts_email_unique ON public.contacts(organization_id,entity_id,lower(btrim(email))) WHERE email<>'';
CREATE TABLE public.product_prices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,entity_product_id uuid NOT NULL,amount numeric(18,6) NOT NULL CHECK(amount>=0 AND amount<1000000000000),currency text NOT NULL CHECK(currency ~ '^[A-Z]{3}$'),unit text NOT NULL CHECK(length(btrim(unit)) BETWEEN 1 AND 40),min_quantity numeric(18,6) NOT NULL CHECK(min_quantity>0 AND min_quantity<1000000000000),effective_date date NOT NULL,notes text NOT NULL DEFAULT '' CHECK(length(notes)<=2000),created_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(organization_id,entity_product_id) REFERENCES public.entity_products(organization_id,id),UNIQUE(organization_id,entity_product_id,currency,unit,min_quantity,effective_date));
GRANT SELECT,INSERT ON public.product_prices TO authenticated; GRANT ALL ON public.product_prices TO service_role;
ALTER TABLE public.product_prices ENABLE ROW LEVEL SECURITY;
CREATE POLICY prices_read ON public.product_prices FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.entity_products ep WHERE ep.organization_id=product_prices.organization_id AND ep.id=product_prices.entity_product_id AND public.can_trade_entity(ep.organization_id,ep.entity_id,false)));
CREATE POLICY prices_insert ON public.product_prices FOR INSERT TO authenticated WITH CHECK(created_by=auth.uid() AND EXISTS(SELECT 1 FROM public.entity_products ep WHERE ep.organization_id=product_prices.organization_id AND ep.id=product_prices.entity_product_id AND public.can_trade_entity(ep.organization_id,ep.entity_id,true)));
CREATE INDEX prices_history ON public.product_prices(organization_id,entity_product_id,currency,effective_date DESC);
CREATE TABLE public.entity_relationships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,source_entity_id uuid NOT NULL,target_entity_id uuid NOT NULL,relationship_type text NOT NULL CHECK(relationship_type IN ('supplier','manufacturer','distributor','partner')),notes text NOT NULL DEFAULT '' CHECK(length(notes)<=2000),created_at timestamptz NOT NULL DEFAULT now(),CHECK(source_entity_id<>target_entity_id),FOREIGN KEY(organization_id,source_entity_id) REFERENCES public.entities(organization_id,id),FOREIGN KEY(organization_id,target_entity_id) REFERENCES public.entities(organization_id,id),UNIQUE(organization_id,source_entity_id,target_entity_id,relationship_type));
GRANT SELECT,INSERT,DELETE ON public.entity_relationships TO authenticated; GRANT UPDATE(notes) ON public.entity_relationships TO authenticated; GRANT ALL ON public.entity_relationships TO service_role;
ALTER TABLE public.entity_relationships ENABLE ROW LEVEL SECURITY;
CREATE POLICY relationships_read ON public.entity_relationships FOR SELECT TO authenticated USING(public.can_trade_entity(organization_id,source_entity_id,false) AND public.can_trade_entity(organization_id,target_entity_id,false));
CREATE POLICY relationships_insert ON public.entity_relationships FOR INSERT TO authenticated WITH CHECK(public.can_trade_entity(organization_id,source_entity_id,true) AND public.can_trade_entity(organization_id,target_entity_id,true));
CREATE POLICY relationships_update ON public.entity_relationships FOR UPDATE TO authenticated USING(public.can_trade_entity(organization_id,source_entity_id,true) AND public.can_trade_entity(organization_id,target_entity_id,true)) WITH CHECK(public.can_trade_entity(organization_id,source_entity_id,true) AND public.can_trade_entity(organization_id,target_entity_id,true));
CREATE POLICY relationships_delete ON public.entity_relationships FOR DELETE TO authenticated USING(public.can_trade_entity(organization_id,source_entity_id,true) AND public.can_trade_entity(organization_id,target_entity_id,true));
REVOKE ALL ON public.products,public.entity_products,public.contacts,public.product_prices,public.entity_relationships FROM anon;
CREATE FUNCTION public.import_trade_catalogue(p_org uuid,p_supplier uuid,p_rows jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$ DECLARE r jsonb; pid uuid; lid uuid; added integer:=0; skipped integer:=0; BEGIN
IF NOT public.has_org_role(p_org,ARRAY['owner','admin']) THEN RAISE EXCEPTION 'Trade access denied'; END IF;
IF p_supplier IS NOT NULL AND NOT public.can_trade_entity(p_org,p_supplier,true) THEN RAISE EXCEPTION 'Supplier access denied'; END IF;
IF jsonb_typeof(p_rows)<>'array' OR jsonb_array_length(p_rows) NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'Import requires 1 to 500 rows'; END IF;
FOR r IN SELECT * FROM jsonb_array_elements(p_rows) LOOP
IF r ? 'amount' AND p_supplier IS NULL THEN RAISE EXCEPTION 'A supplier is required for prices'; END IF;
pid:=NULL;
INSERT INTO public.products(organization_id,sku,name,category,description,unit,status) VALUES(p_org,r->>'sku',r->>'name',coalesce(r->>'category',''),coalesce(r->>'description',''),coalesce(r->>'unit','piece'),coalesce(r->>'status','active')) ON CONFLICT DO NOTHING RETURNING id INTO pid;
IF pid IS NULL THEN skipped:=skipped+1; CONTINUE; END IF;
IF p_supplier IS NOT NULL THEN
INSERT INTO public.entity_products(organization_id,entity_id,product_id,moq,capacity,packaging) VALUES(p_org,p_supplier,pid,coalesce((r->>'moq')::numeric,1),coalesce(r->>'capacity',''),coalesce(r->>'packaging','')) RETURNING id INTO lid;
IF r ? 'amount' THEN INSERT INTO public.product_prices(organization_id,entity_product_id,amount,currency,unit,min_quantity,effective_date) VALUES(p_org,lid,(r->>'amount')::numeric,r->>'currency',coalesce(r->>'unit','piece'),coalesce((r->>'moq')::numeric,1),(r->>'effective_date')::date); END IF;
END IF; added:=added+1; END LOOP; RETURN jsonb_build_object('inserted',added,'skipped',skipped); END $$;
REVOKE ALL ON FUNCTION public.import_trade_catalogue(uuid,uuid,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.import_trade_catalogue(uuid,uuid,jsonb) TO authenticated;
CREATE FUNCTION public.validate_trade_profile() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ DECLARE p jsonb; BEGIN
p:=NEW.data->'trade_profile'; IF p IS NULL OR p='null'::jsonb THEN RETURN NEW; END IF;
IF jsonb_typeof(p)<>'object' OR coalesce(p->>'kind','') NOT IN ('manufacturer','supplier','both') OR length(btrim(coalesce(p->>'legal_name',''))) NOT BETWEEN 1 AND 160 OR jsonb_typeof(p->'certifications') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Invalid manufacturer profile'; END IF;
IF jsonb_array_length(p->'certifications')>50 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'certifications') c WHERE jsonb_typeof(c)<>'string' OR length(c#>>'{}') NOT BETWEEN 1 AND 100) THEN RAISE EXCEPTION 'Invalid certifications'; END IF;
IF length(coalesce(p->>'country',''))>80 OR length(coalesce(p->>'address',''))>1000 OR length(coalesce(p->>'capacity',''))>500 OR length(coalesce(p->>'notes',''))>5000 OR (coalesce(p->>'website','')<>'' AND p->>'website' !~ '^https?://[^[:space:]]+$') THEN RAISE EXCEPTION 'Invalid profile details'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.validate_trade_profile() FROM PUBLIC,anon;
CREATE TRIGGER trade_profile_validation BEFORE INSERT OR UPDATE ON public.entities FOR EACH ROW EXECUTE FUNCTION public.validate_trade_profile();
CREATE FUNCTION public.stamp_trade_product() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN NEW.updated_at:=now(); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.stamp_trade_product() FROM PUBLIC,anon;
CREATE TRIGGER stamp_trade_product BEFORE UPDATE ON public.products FOR EACH ROW EXECUTE FUNCTION public.stamp_trade_product();
COMMENT ON COLUMN public.entities.data IS 'Metadata record values; optional trade_profile stores manufacturer/supplier profile without separate entity-type tables.';
COMMENT ON TABLE public.product_prices IS 'Append-only price quotes; series separated by supplier-product, ISO currency, unit, quantity tier and effective date.';